class Solution { struct Node{int next[2]={-1,-1},count=0;};int countLess(vector<int>& nums,int limit){vector<Node> trie(1);int answer=0;for(int value:nums){int node=0;for(int bit=15;bit>=0&&node>=0;--bit){int digit=value>>bit&1,bound=limit>>bit&1;if(bound){int same=trie[node].next[digit];if(same>=0)answer+=trie[same].count;node=trie[node].next[digit^1];}else node=trie[node].next[digit];}node=0;++trie[node].count;for(int bit=15;bit>=0;--bit){int digit=value>>bit&1;if(trie[node].next[digit]<0){trie[node].next[digit]=trie.size();trie.push_back({});}node=trie[node].next[digit];++trie[node].count;}}return answer;}public:int countPairs(vector<int>& nums,int low,int high){return countLess(nums,high+1)-countLess(nums,low);} };
